}

head.src/mw/request_log.ts:
export function logRequest(r: Request, user?: { email: string }): void {
  log.info("request", {
    method: r.method,
    path: new URL(r.url).pathname,
    ms: Date.now() - started(r),
    ip: r.headers.get("x-forwarded-for"),
    email: user?.email,
  });
}
